"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _include_target(line):
    parts = line.strip().split(None, 1)
    if not parts or parts[0] != INCLUDE_DIRECTIVE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("@include requires a path")
    return parts[1].strip()


def _expand(path, lines, stack):
    base_dir = os.path.dirname(os.path.abspath(path))
    result = []
    for line in lines:
        target = _include_target(line)
        if target is None:
            result.append(line)
            continue
        include_path = os.path.join(base_dir, target)
        real = os.path.realpath(include_path)
        if real in stack:
            raise ConfigError(
                "include cycle detected: {!r} included from {!r}".format(
                    target, path
                )
            )
        if not os.path.isfile(include_path):
            raise ConfigError(
                "included file not found: {!r} (from {!r})".format(target, path)
            )
        try:
            included = _read_lines(include_path)
        except OSError as exc:
            raise ConfigError(
                "cannot read included file {!r}: {}".format(include_path, exc)
            )
        stack.add(real)
        try:
            result.extend(_expand(include_path, included, stack))
        finally:
            stack.discard(real)
    return result


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced in place by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read_lines(path)
    lines = _expand(path, lines, {os.path.realpath(path)})
    return parse_lines(lines)


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
